<?php include '../auth/cek_login.php';include '../koneksi.php';$err='';if(isset($_POST['simpan'])){$no=trim($_POST['nomor_polisi']);$merk=trim($_POST['merk']);$tipe=trim($_POST['tipe']);$tahun=(int)$_POST['tahun'];$warna=trim($_POST['warna']);$harga=(int)$_POST['harga_sewa'];$s=mysqli_prepare($conn,'INSERT INTO mobil(nomor_polisi,merk,tipe,tahun,warna,harga_sewa) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'sssisi',$no,$merk,$tipe,$tahun,$warna,$harga);if(mysqli_stmt_execute($s)){header('Location: index.php');exit;}else{$err='Gagal menyimpan data.';}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Tambah Mobil</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content form-page"><h1>Tambah Mobil</h1><?php if($err):?><div class="error"><?=$err?></div><?php endif;?><form method="post"><label>Nomor Polisi</label><input name="nomor_polisi" required><label>Merk</label><input name="merk" required><label>Tipe</label><input name="tipe" required><label>Tahun</label><input type="number" name="tahun" required><label>Warna</label><input name="warna" required><label>Harga Sewa/Hari</label><input type="number" name="harga_sewa" required><button name="simpan">Simpan</button> <a class="btn-delete" href="index.php">Kembali</a></form></div></body></html>
